"use strict";
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const store={get(k,d){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v)}catch(e){return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){return false}}};
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const norm=s=>String(s).normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
const pad=(n,l=2)=>String(n).padStart(l,"0");
const short=(s,max=130)=>{s=String(s||"").replace(/\s+/g," ").trim();if(s.length<=max)return s;const cut=s.slice(0,max);const i=cut.lastIndexOf(" ");return cut.slice(0,i>60?i:max).replace(/[,;:\s]+$/,"")+"…"};
const flagEmoji=c=>String.fromCodePoint(...[...String(c).toUpperCase()].map(x=>127397+x.charCodeAt(0)));
const flagImg=(c,cls="")=>`<img class="flag ${cls}" data-code="${c}" src="https://flagcdn.com/w40/${c.toLowerCase()}.png" srcset="https://flagcdn.com/w80/${c.toLowerCase()}.png 2x" alt="" loading="lazy" width="20" height="14">`;
const reduced=()=>matchMedia("(prefers-reduced-motion: reduce)").matches;
