/* ---------- crossfading background layers ---------- */
function setLayer(host,url,cls="bglayer"){
  if(!host)return;
  if(!url){return}
  if(host.dataset.url===url)return;host.dataset.url=url;
  const img=new Image();
  img.onload=()=>{if(host.dataset.url!==url)return;const d=document.createElement("div");d.className=cls;d.style.backgroundImage=`url("${url}")`;host.appendChild(d);requestAnimationFrame(()=>requestAnimationFrame(()=>d.classList.add("in")));const old=[...host.children].filter(x=>x!==d&&x.classList.contains(cls));setTimeout(()=>old.forEach(o=>o.remove()),1300)};
  img.onerror=()=>{if(host.dataset.url===url)delete host.dataset.url};
  img.src=url;
}
/* ================= DISCOVER v3 — Wikipedia / Wikivoyage / REST Countries ================= */
const memo=new Map();
function jget(url){if(memo.has(url))return memo.get(url);const p=fetch(url).then(r=>{if(!r.ok)throw Error(r.status);return r.json()});memo.set(url,p);p.catch(()=>memo.delete(url));return p}
const WAPI="https://en.wikipedia.org/w/api.php?format=json&origin=*&action=query";
const wikiSummary=(l,title)=>jget(`https://${l}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(title.replace(/ /g,"_"))}?redirect=true`);
const getFacts=code=>jget(`https://restcountries.com/v3.1/alpha/${code}?fields=capital,region,subregion,population,languages,currencies,area,latlng`).then(d=>Array.isArray(d)?d[0]:d);

/* real photos + coordinates for exact article titles (batched, cached) */
const thumbCache=new Map();
async function wikiThumbs(titles,size=900){
  titles=[...new Set(titles.filter(Boolean))];
  const need=titles.filter(x=>!thumbCache.has(size+"|"+x));
  for(let i=0;i<need.length;i+=40){
    const chunk=need.slice(i,i+40);
    try{
      const d=await jget(`${WAPI}&redirects=1&titles=${encodeURIComponent(chunk.join("|"))}&prop=pageimages%7Ccoordinates&piprop=thumbnail&pithumbsize=${size}&pilimit=max&colimit=max`);
      const q=d.query||{};
      const n1=Object.fromEntries((q.normalized||[]).map(x=>[x.from,x.to]));
      const rd=Object.fromEntries((q.redirects||[]).map(x=>[x.from,x.to]));
      const byTitle=Object.fromEntries(Object.values(q.pages||{}).map(p=>[p.title,p]));
      chunk.forEach(x=>{let n=n1[x]||x;n=rd[n]||n;const p=byTitle[n];const c=p&&p.coordinates&&p.coordinates[0];thumbCache.set(size+"|"+x,p?{url:p.thumbnail?.source||null,lat:c?c.lat:null,lng:c?c.lon:null,title:p.title}:{url:null})});
    }catch(e){chunk.forEach(x=>thumbCache.set(size+"|"+x,{url:null}))}
  }
  return new Map(titles.map(x=>[x,thumbCache.get(size+"|"+x)||{url:null}]));
}
/* last resort when an exact title has no photo: first search hit that has one */
async function searchImage(q,size=900){
  try{const d=await jget(`${WAPI}&generator=search&gsrsearch=${encodeURIComponent(q)}&gsrlimit=6&gsrnamespace=0&prop=pageimages&piprop=thumbnail&pithumbsize=${size}`);
    const p=Object.values(d.query?.pages||{}).sort((a,b)=>a.index-b.index).find(x=>x.thumbnail);return p?p.thumbnail.source:null}catch(e){return null}
}
function paintEl(e,url){if(e.tagName==="IMG"){e.src=url}else{e.style.backgroundImage=`url("${url}")`}e.classList.add("has-photo")}
async function hydrateWiki(root=document){
  const els=$$("[data-wiki]:not([data-wdone])",root);if(!els.length)return;
  els.forEach(e=>e.dataset.wdone="1");
  const groups={};els.forEach(e=>{const s=+e.dataset.wsize||900;(groups[s]||(groups[s]=[])).push(e)});
  for(const s in groups){
    const m=await wikiThumbs(groups[s].map(e=>e.dataset.wiki),+s);
    for(const e of groups[s]){
      const r=m.get(e.dataset.wiki);
      if(r&&r.url)paintEl(e,r.url);
      else searchImage(e.dataset.wiki+(e.dataset.wctx?" "+e.dataset.wctx:""),+s).then(u=>{if(u)paintEl(e,u);else if(e.tagName==="IMG")e.style.display="none"});
    }
  }
}
/* broken <img> → try Wikipedia once, then hide (gradient shows through) */
document.addEventListener("error",e=>{const img=e.target;if(!(img instanceof HTMLImageElement))return;
  if(img.classList.contains("flag")){const s=document.createElement("span");s.className="flag-emoji";s.textContent=flagEmoji(img.dataset.code);img.replaceWith(s);return}
  if(img.dataset.wiki&&!img.dataset.tried){img.dataset.tried="1";searchImage(img.dataset.wiki+" "+(img.dataset.wctx||"")).then(u=>{if(u)img.src=u;else img.style.display="none"});return}
  img.style.display="none"},true);

/* ---------- attractions: category pages ranked by pageviews, fallback to search ---------- */
const enBase=code=>WIKI_EN[code]||BY_CODE[code].en;
function viewSum(p){const v=p.pageviews;return v?Object.values(v).reduce((a,b)=>a+(b||0),0):0}
const NOISE=/^(list of|lists of|outline of|tourism in|category:|template:|portal:)|\b(airport|railway station|metro station|stadium|university|hospital|bank|company|prison|disaster)\b/i;
async function rankedPages(url){
  const d=await jget(url).catch(()=>null);
  return Object.values(d?.query?.pages||{}).filter(p=>p.thumbnail&&!NOISE.test(p.title)).sort((a,b)=>viewSum(b)-viewSum(a));
}
async function getAttractions(code){
  const key="att:"+code;if(memo.has(key))return memo.get(key);
  const p=(async()=>{
    const base=enBase(code),cn=norm(base.replace(/\s*\(.*\)/,""));
    let pages=[];
    for(const nm of [base,"the "+base]){
      pages=await rankedPages(`${WAPI}&generator=categorymembers&gcmtitle=${encodeURIComponent("Category:Tourist attractions in "+nm)}&gcmtype=page&gcmlimit=60&prop=pageviews%7Cpageimages&piprop=thumbnail&pithumbsize=800&pilimit=max`);
      if(pages.length>=3)break;
    }
    if(pages.length<3){
      pages=await rankedPages(`${WAPI}&generator=search&gsrsearch=${encodeURIComponent(base.replace(/\s*\(.*\)/,"")+" tourist attractions landmarks")}&gsrlimit=30&gsrnamespace=0&prop=pageviews%7Cpageimages&piprop=thumbnail&pithumbsize=800&pilimit=max`);
    }
    const top=pages.slice(0,12);if(!top.length)return[];
    const ex=await jget(`${WAPI}&redirects=1&titles=${encodeURIComponent(top.map(x=>x.title).join("|"))}&prop=extracts%7Ccoordinates&exintro=1&explaintext=1&exsentences=2&exlimit=max&colimit=max`).catch(()=>null);
    const by=Object.fromEntries(Object.values(ex?.query?.pages||{}).map(x=>[x.title,x]));
    let list=top.map(x=>{const e=by[x.title]||{};const c=e.coordinates&&e.coordinates[0];return{title:x.title,text:short(e.extract||"",120),img:x.thumbnail.source,lat:c?c.lat:null,lng:c?c.lon:null,mentions:norm(e.extract||"").includes(cn)}});
    const rel=list.filter(x=>x.mentions);if(rel.length>=3)list=rel;
    return list.filter(x=>x.text).slice(0,6);
  })();
  memo.set(key,p);return p;
}
const FOOD_Q={en:"traditional food dishes cuisine",fr:"cuisine plats traditionnels",ar:"أكلات تقليدية مطبخ",es:"comida platos tradicionales cocina",de:"traditionelle Gerichte Küche",it:"piatti tipici cucina"};
async function getFood(code){
  const key="food:"+code+lang;if(memo.has(key))return memo.get(key);
  const p=(async()=>{
    const l=lang,name=l==="en"?enBase(code).replace(/\s*\(.*\)/,""):nm(code);
    const run=async L=>{
      const country=L==="en"?enBase(code).replace(/\s*\(.*\)/,""):nm(code);
      const q=`${country} ${FOOD_Q[L]||FOOD_Q.en}`;
      const d=await jget(`https://${L}.wikipedia.org/w/api.php?format=json&origin=*&action=query&generator=search&gsrsearch=${encodeURIComponent(q)}&gsrlimit=20&gsrnamespace=0&prop=pageimages%7Cextracts&piprop=thumbnail&pithumbsize=500&exintro=1&explaintext=1&exsentences=2&exlimit=max`).catch(()=>null);
      const pages=Object.values(d?.query?.pages||{}).sort((a,b)=>a.index-b.index);
      const foodWords=/food|dish|cuisine|culinary|recipe|ingredient|meal|traditional|specialt(y|ties)|gastronom|cooking|rice|noodle|soup|bread|stew|dessert/i;
      return pages.filter(x=>x.extract&&x.extract.length>45&&!NOISE.test(x.title)&&foodWords.test(x.title+" "+x.extract))
        .filter(x=>!/(restaurant|chef|food company|brand|festival|film|album)/i.test(x.title))
        .slice(0,4).map(x=>({emoji:"🍽️",title:x.title,text:short(x.extract,110),img:x.thumbnail?.source}));
    };
    let out=await run(l);if(out.length<2&&l!=="en")out=await run("en");return out;
  })();
  memo.set(key,p);return p;
}
async function getDesc(code){const cur=CURATED[code];if(cur&&lang==="en")return cur.desc;
  const tryL=async L=>{const s=await wikiSummary(L,L==="en"?enBase(code):nm(code));return s.extract?short(s.extract,230):null};
  try{const d=await tryL(lang);if(d)return d}catch(e){}
  if(lang!=="en"){try{const d=await tryL("en");if(d)return d}catch(e){}}
  return cur?.desc||t("fallbackDesc")}

/* ---------- Wikivoyage (travel guide text) ---------- */
function parseSections(txt){const secs=[];let cur={h:"",lvl:1,b:[]};
  for(const ln of txt.split("\n")){const m=ln.match(/^(={2,})\s*(.+?)\s*\1\s*$/);if(m){secs.push(cur);cur={h:m[2],lvl:m[1].length,b:[]}}else cur.b.push(ln)}
  secs.push(cur);
  return secs.map(s=>({h:s.h,lvl:s.lvl,t:s.b.join("\n").replace(/\n{3,}/g,"\n\n").trim()})).filter(s=>s.h&&s.lvl===2&&s.t.length>80)}
async function getVoyage(code){
  const key="voy:"+code+lang;if(memo.has(key))return memo.get(key);
  const p=(async()=>{
    const tryL=async L=>{const title=L==="en"?enBase(code):nm(code);
      const d=await jget(`https://${L}.wikivoyage.org/w/api.php?format=json&origin=*&action=query&redirects=1&prop=extracts&explaintext=1&exsectionformat=wiki&titles=${encodeURIComponent(title)}`);
      const pg=Object.values(d.query?.pages||{})[0];if(!pg||!pg.extract)throw Error("none");const s=parseSections(pg.extract);if(!s.length)throw Error("none");return s};
    const first=["en","fr","es","de","it"].includes(lang)?lang:"en";
    try{return await tryL(first)}catch(e){if(first!=="en"){try{return await tryL("en")}catch(e2){}}}
    return[];
  })();
  memo.set(key,p);return p;
}
