/* ---------- facts ---------- */
function currencyName(code,v){try{return new Intl.DisplayNames([lang],{type:"currency"}).of(code)||v.name}catch(e){return v.name}}
function renderFacts(d){const box=$("#countryFacts");if(!d){box.innerHTML="";return}const f=[];const nf=new Intl.NumberFormat(lang,{notation:"compact",maximumFractionDigits:1});
  if(d.capital&&d.capital.length)f.push(["capital",d.capital.slice(0,2).join(", ")]);
  if(d.subregion||d.region)f.push(["region",d.subregion||d.region]);
  if(d.population)f.push(["population",nf.format(d.population)]);
  if(d.area)f.push(["area",nf.format(d.area)+" km²"]);
  if(d.languages)f.push(["languagesF",Object.values(d.languages).slice(0,3).join(", ")]);
  if(d.currencies)f.push(["currencyF",Object.entries(d.currencies).slice(0,2).map(([c,v])=>currencyName(c,v)).join(", ")]);
  box.innerHTML=f.map(([k,v])=>`<div class="fact"><small>${t(k)}</small><b>${esc(v)}</b></div>`).join("")}

/* ---------- place + food cards ---------- */
function placeCard(p,i,country){const q=encodeURIComponent(`${p.title}, ${country}`);
  const img=p.img?`<img src="${esc(p.img)}" alt="${esc(p.title)}" loading="lazy" data-wiki="${esc(p.title)}" data-wctx="${esc(country)}">`:(p.wiki?`<img data-wiki="${esc(p.wiki)}" data-wctx="${esc(p.title+" "+country)}" alt="${esc(p.title)}" loading="lazy">`:"");
  return `<a class="destination-card" id="place-${i}" href="https://www.google.com/maps/search/?api=1&query=${q}" target="_blank" rel="noopener" style="animation-delay:${i*80}ms"><div class="destination-image"><i class="di-fallback">${p.emoji||"✦"}</i>${img}</div><div class="destination-info"><span>${esc(p.tag)}</span><h4>${esc(p.title)}</h4><p>${esc(p.text)}</p><em class="maps-link">${t("mapsLink")}</em></div></a>`}
function foodCard(f){return `<div class="food-card">${f.img?`<img class="food-thumb" src="${esc(f.img)}" alt="" loading="lazy">`:`<span class="food-emoji">${f.emoji}</span>`}<div><b>${esc(f.title)}</b><small>${esc(f.text)}</small></div></div>`}
const skeletons=n=>Array.from({length:n},()=>'<div class="skeleton"></div>').join("");
function setPlaces(list,country){S.places=list;$("#destinationGrid").innerHTML=list.map((p,i)=>placeCard(p,i,country)).join("");$("#placeCount").textContent=`${pad(list.length)} ${t("placesWord")}`;hydrateWiki($("#destinationGrid"));if(typeof paintGuide==="function")paintGuide()}
