function applyCountryTheme(code){
  let theme=COUNTRY_THEMES[code];
  if(!theme){
    let hash=0;for(const ch of code)hash=(hash*31+ch.charCodeAt(0))>>>0;
    const hue=hash%360;
    theme={bg:`hsl(${hue} 27% 9%)`,panel:`hsl(${hue} 27% 15%)`,panel2:`hsl(${hue} 29% 21%)`,gold:`hsl(${(hue+34)%360} 48% 70%)`,mint:`hsl(${(hue+155)%360} 35% 69%)`,glow:`hsla(${hue} 65% 42% / .18)`};
  }
  const root=document.documentElement;
  Object.entries({"--bg":theme.bg,"--panel":theme.panel,"--panel2":theme.panel2,"--gold":theme.gold,"--mint":theme.mint,"--country-glow":theme.glow}).forEach(([k,v])=>root.style.setProperty(k,v));
  document.body.dataset.country=code;
}
function setCountry(code,opts={}){
  if(!BY_CODE[code])return;
  const changed=code!==S.code;S.code=code;const token=++renderToken;store.set("discoverLast",code);applyCountryTheme(code);
  if(!opts.silent){try{history.replaceState(null,"","?c="+code+location.hash)}catch(e){}}
  if(changed)resetChallengeForm();
  $("#countrySelect").value=code;
  document.body.classList.remove("swap");void document.body.offsetWidth;document.body.classList.add("swap");
  renderChips();renderTasks();paintGlobe();
  renderContent(code,token);
  if(opts.fly!==false)flyTo(code);
}
function goCountry(code,target="#explore"){setCountry(code);$(target).scrollIntoView({behavior:"smooth"})}

/* ---------- globe ---------- */
let globe=null,globeStarted=false,idleTimer=null,cloudMesh=null;const featByCode={};
const GEO_URLS=["https://cdn.jsdelivr.net/gh/vasturiano/globe.gl@master/example/datasets/ne_110m_admin_0_countries.geojson","https://raw.githubusercontent.com/vasturiano/globe.gl/master/example/datasets/ne_110m_admin_0_countries.geojson","https://raw.githubusercontent.com/holtzy/D3-graph-gallery/master/DATA/world.geojson"];
const TEX="https://cdn.jsdelivr.net/npm/three-globe@2/example/img/";
function geoCode(f){const p=f.properties||{};let c=p.ISO_A2_EH;if(!c||c==="-99")c=p.ISO_A2;if(c&&c!=="-99"&&BY_CODE[c])return c;const n=p.ADMIN||p.NAME||p.name;if(n==="France")return"FR";if(n==="Norway")return"NO";if(NAME_ALIAS[n])return NAME_ALIAS[n];const m=n&&COUNTRY_LIST.find(x=>x.en.toLowerCase()===String(n).toLowerCase());return m?m.code:null}
async function loadGeo(){for(const u of GEO_URLS){try{const r=await fetch(u);if(!r.ok)continue;const j=await r.json();if(j.features&&j.features.length)return j.features}catch(e){}}throw Error("geo")}
function featureCenter(f){const g=f.geometry;if(!g)return null;const polys=g.type==="Polygon"?[g.coordinates]:g.coordinates;let best=polys[0],bn=0;polys.forEach(p=>{if(p[0].length>bn){bn=p[0].length;best=p}});let minX=180,maxX=-180,minY=90,maxY=-90;best[0].forEach(([x,y])=>{if(x<minX)minX=x;if(x>maxX)maxX=x;if(y<minY)minY=y;if(y>maxY)maxY=y});const span=Math.max(maxX-minX,(maxY-minY)*1.4);return{lat:(minY+maxY)/2,lng:(minX+maxX)/2,alt:Math.min(2.3,Math.max(.7,.6+span/38))}}
function paintGlobe(){if(!globe)return;const visited=new Set(getBook().map(b=>b.code));
  globe.polygonCapColor(f=>{const c=f.__code;if(c&&c===S.code)return"rgba(217,180,123,.55)";if(c&&c===S.hover)return"rgba(255,255,255,.22)";if(c&&visited.has(c))return"rgba(134,203,184,.38)";return"rgba(0,0,0,0)"})
   .polygonAltitude(f=>f.__code&&f.__code===S.code?.02:(f.__code&&f.__code===S.hover?.01:.003));
  const pos=S.latlng[S.code]&&!featByCode[S.code]?{lat:S.latlng[S.code][0],lng:S.latlng[S.code][1]}:(featByCode[S.code]?featureCenter(featByCode[S.code]):null);
  globe.ringsData(pos?[{lat:pos.lat,lng:pos.lng}]:[])}
function setPins(pins){S.pins=pins;if(!globe)return;globe.pointsData(pins).labelsData(pins)}
function stopAuto(){if(!globe)return;const c=globe.controls();c.autoRotate=false;clearTimeout(idleTimer);idleTimer=setTimeout(()=>{c.autoRotate=true},7000)}
function flyTo(code){if(!globe)return;let pos=null;const f=featByCode[code];if(f)pos=featureCenter(f);if(!pos&&S.latlng[code])pos={lat:S.latlng[code][0],lng:S.latlng[code][1],alt:1.2};if(!pos)return;stopAuto();globe.pointOfView({lat:pos.lat,lng:pos.lng,altitude:pos.alt},1400)}
/* realism extras: water specularity, cloud layer, lighting — each wrapped so failures just skip the effect */
function loadImg(src){return new Promise((res,rej)=>{const i=new Image();i.crossOrigin="anonymous";i.onload=()=>res(i);i.onerror=rej;i.src=src})}
async function enhanceGlobe(){
  try{
    const m=globe.globeMaterial();
    for(let k=0;k<30&&!m.map;k++)await wait(200);
    const Tex=m.map.constructor,Col=m.color.constructor;
    m.bumpScale=6;
    try{const w=await loadImg(TEX+"earth-water.png");const tx=new Tex(w);tx.needsUpdate=true;m.specularMap=tx;m.specular=new Col("#4b6a86");m.shininess=22;m.needsUpdate=true}catch(e){}
    try{
      const c=await loadImg("https://cdn.jsdelivr.net/gh/vasturiano/three-globe@master/example/clouds/clouds.png");
      let globeMesh=null;globe.scene().traverse(o=>{if(!globeMesh&&o.isMesh&&o.geometry&&o.geometry.type==="SphereGeometry"&&o.material===m)globeMesh=o});
      if(globeMesh){const Geo=globeMesh.geometry.constructor,Mat=m.constructor,Mesh=globeMesh.constructor,r=globeMesh.geometry.parameters.radius;
        const tx=new Tex(c);tx.needsUpdate=true;
        cloudMesh=new Mesh(new Geo(r*1.012,75,75),new Mat({map:tx,transparent:true,opacity:.42,depthWrite:false}));
        cloudMesh.renderOrder=2;globe.scene().add(cloudMesh);
        if(!reduced())(function spin(){if(cloudMesh){cloudMesh.rotation.y+=.00022;requestAnimationFrame(spin)}})();}
    }catch(e){}
    try{const L=globe.lights&&globe.lights();if(L){const sun=L.find(l=>l.type==="DirectionalLight");if(sun){sun.intensity=1.15}}}catch(e){}
  }catch(e){}
}
async function initGlobe(){const host=$("#globeViz");
  const fail=()=>{host.innerHTML=`<div class="globe-loading">${esc(t("globeFail"))}</div>`;$("#globeStatus").textContent=""};
  if(typeof Globe!=="function")return fail();
  let feats;try{feats=await loadGeo()}catch(e){return fail()}
  feats.forEach(f=>{f.__code=geoCode(f);if(f.__code&&!featByCode[f.__code])featByCode[f.__code]=f});
  host.innerHTML="";
  globe=Globe()(host).width(host.clientWidth).height(host.clientHeight).backgroundColor("rgba(0,0,0,0)")
    .backgroundImageUrl(TEX+"night-sky.png")
    .globeImageUrl(TEX+"earth-blue-marble.jpg").bumpImageUrl(TEX+"earth-topology.png")
    .showAtmosphere(true).atmosphereColor("#7fb8ff").atmosphereAltitude(.2)
    .polygonsData(feats).polygonSideColor(()=>"rgba(255,255,255,.04)").polygonStrokeColor(()=>"rgba(255,255,255,.28)").polygonsTransitionDuration(300)
    .polygonLabel(f=>f.__code?`<div class="globe-tip">${flagEmoji(f.__code)} ${esc(nm(f.__code))}</div>`:`<div class="globe-tip">${esc(f.properties?.ADMIN||f.properties?.name||"")}</div>`)
    .onPolygonHover(f=>{S.hover=f?f.__code:null;host.style.cursor=f&&f.__code?"pointer":"grab";paintGlobe()})
    .onPolygonClick(f=>{if(f&&f.__code)goCountry(f.__code);else if(f)toast(f.properties?.ADMIN||f.properties?.name||"")})
    .pointLat("lat").pointLng("lng").pointColor(()=>"#ffd9a0").pointAltitude(.04).pointRadius(.35).pointResolution(8)
    .onPointClick(p=>{const el=$("#place-"+p.idx);if(el){el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("flash");setTimeout(()=>el.classList.remove("flash"),1800)}})
    .labelLat("lat").labelLng("lng").labelText("title").labelSize(.55).labelDotRadius(.3).labelColor(()=>"rgba(255,236,205,.95)").labelAltitude(.05).labelResolution(2)
    .onLabelClick(p=>{const el=$("#place-"+p.idx);if(el){el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("flash");setTimeout(()=>el.classList.remove("flash"),1800)}})
    .ringColor(()=>tt=>`rgba(255,217,160,${1-tt})`).ringMaxRadius(5).ringPropagationSpeed(2.2).ringRepeatPeriod(1400).ringLat("lat").ringLng("lng");
  const c=globe.controls();c.autoRotate=true;c.autoRotateSpeed=.35;c.enableDamping=true;c.minDistance=130;c.maxDistance=420;
  globe.pointOfView({lat:25,lng:12,altitude:2.3});
  host.addEventListener("pointerdown",stopAuto);host.addEventListener("wheel",stopAuto,{passive:true});
  new ResizeObserver(()=>{if(globe)globe.width(host.clientWidth).height(host.clientHeight)}).observe(host);
  $("#globeStatus").textContent=t("globeReady");paintGlobe();setPins(S.pins||[]);setTimeout(()=>flyTo(S.code),500);
  enhanceGlobe()}
function whenGlobeReady(cb){if(typeof Globe==="function")cb();else window.addEventListener("load",cb,{once:true})}
function observeGlobe(){if("IntersectionObserver"in window){new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting&&!globeStarted){globeStarted=true;whenGlobeReady(initGlobe)}if(globe){e.isIntersecting?globe.resumeAnimation():globe.pauseAnimation()}}),{rootMargin:"300px"}).observe($("#globeViz"))}else whenGlobeReady(initGlobe)}

